<?php
 namespace Pterodactyl\Services\Dezerx\Staff; use Illuminate\Database\Eloquent\Builder; use Pterodactyl\Models\Dezerx\StaffMessage; use Pterodactyl\Models\Dezerx\StaffProfile; use Pterodactyl\Models\Dezerx\StaffRequest; use Pterodactyl\Models\Dezerx\StaffRequestEvent; use Pterodactyl\Models\User; class StaffRecord { private const ENDINGS = [ StaffRequestEvent::RESIGNED, StaffRequestEvent::RESOLVED, StaffRequestEvent::REVOKED, StaffRequestEvent::EXPIRED, StaffRequestEvent::WITHDRAWN, ]; private const HISTORY = 500; public static function forUser(User $staff): array { $mine = StaffRequestEvent::query() ->where('actor_id', $staff->id) ->whereIn('action', [ StaffRequestEvent::GRANTED, StaffRequestEvent::RESIGNED, StaffRequestEvent::RESOLVED, StaffRequestEvent::DECLINED, ]) ->orderByDesc('id') ->limit(self::HISTORY) ->get(['id', 'request_id', 'action', 'created_at']); $granted = $mine->where('action', StaffRequestEvent::GRANTED); $requestIds = $granted->pluck('request_id')->unique()->values(); $servers = $requestIds->isEmpty() ? 0 : (int) StaffRequest::query() ->whereIn('id', $requestIds) ->distinct() ->count('server_id'); $expired = $requestIds->isEmpty() ? 0 : (int) StaffRequest::query() ->whereIn('id', $requestIds) ->where('staff_id', $staff->id) ->where('status', StaffRequest::EXPIRED) ->count(); $active = (int) StaffRequest::query() ->where('staff_id', $staff->id) ->whereIn('status', [StaffRequest::CLAIMED, StaffRequest::ACTIVE]) ->count(); $profile = $staff->staffProfile; return [ 'id' => $staff->id, 'username' => $staff->username, 'available' => !($profile instanceof StaffProfile) || $profile->available, 'maxActive' => $profile instanceof StaffProfile ? $profile->max_active : (int) Staff::DEFAULTS['max_active_per_staff'], 'notes' => $profile instanceof StaffProfile ? (string) ($profile->notes ?? '') : '', 'discord' => $profile instanceof StaffProfile ? (string) ($profile->discord_id ?? '') : '', 'taken' => $requestIds->count(), 'servers' => $servers, 'resolved' => $mine->where('action', StaffRequestEvent::RESOLVED)->count(), 'declined' => $mine->where('action', StaffRequestEvent::DECLINED)->count(), 'handedBack' => $mine->where('action', StaffRequestEvent::RESIGNED)->count(), 'expired' => $expired, 'active' => $active, 'minutes' => self::minutesWorked($staff, $requestIds->all()), 'averageClaimSeconds' => self::averageClaimSeconds($staff), 'lastActive' => $profile instanceof StaffProfile && $profile->last_active_at !== null ? $profile->last_active_at->toAtomString() : null, ]; } public static function roster(): array { $records = []; foreach (User::query()->where('staff', true)->orderBy('username')->cursor() as $staff) { $records[] = self::forUser($staff); } return $records; } public static function badges(User $user): array { $queue = 0; if (Staff::canAct($user)) { $queue = (int) app(StaffRequests::class)->queueFor($user)->count() + self::unreadForStaff($user); } $servers = []; foreach ([self::waitingOnOwner($user), self::unreadForOwner($user)] as $rows) { foreach ($rows as $identifier => $total) { $servers[$identifier] = ($servers[$identifier] ?? 0) + (int) $total; } } return [ 'queue' => $queue, 'servers' => (object) $servers, ]; } private static function waitingOnOwner(User $user): array { return StaffRequest::query() ->join('servers', 'servers.id', '=', 'dezerx_staff_requests.server_id') ->where('servers.owner_id', $user->id) ->where(function (Builder $builder) { $builder->where('dezerx_staff_requests.status', StaffRequest::CLAIMED) ->orWhere(function (Builder $inner) { $inner->where('dezerx_staff_requests.status', StaffRequest::PENDING) ->where('dezerx_staff_requests.direction', StaffRequest::DIRECTION_STAFF); }) ->orWhere(function (Builder $inner) { $inner->where('dezerx_staff_requests.status', StaffRequest::ACTIVE) ->whereNotNull('dezerx_staff_requests.extension_minutes'); }); }) ->groupBy('servers.uuidShort') ->selectRaw('servers.uuidShort as identifier, count(*) as total') ->pluck('total', 'identifier') ->all(); } private static function unreadForOwner(User $user): array { return StaffMessage::query() ->join('dezerx_staff_requests', 'dezerx_staff_requests.id', '=', 'dezerx_staff_messages.request_id') ->join('servers', 'servers.id', '=', 'dezerx_staff_requests.server_id') ->where('servers.owner_id', $user->id) ->whereIn('dezerx_staff_requests.status', StaffRequest::OPEN_STATUSES) ->where('dezerx_staff_messages.user_id', '!=', $user->id) ->where(function (Builder $builder) { $builder->whereNull('dezerx_staff_requests.owner_read_at') ->orWhereColumn( 'dezerx_staff_messages.created_at', '>', 'dezerx_staff_requests.owner_read_at' ); }) ->groupBy('servers.uuidShort') ->selectRaw('servers.uuidShort as identifier, count(*) as total') ->pluck('total', 'identifier') ->all(); } private static function unreadForStaff(User $user): int { return (int) StaffMessage::query() ->join('dezerx_staff_requests', 'dezerx_staff_requests.id', '=', 'dezerx_staff_messages.request_id') ->where('dezerx_staff_requests.staff_id', $user->id) ->whereIn('dezerx_staff_requests.status', StaffRequest::OPEN_STATUSES) ->where('dezerx_staff_messages.user_id', '!=', $user->id) ->where(function (Builder $builder) { $builder->whereNull('dezerx_staff_requests.staff_read_at') ->orWhereColumn( 'dezerx_staff_messages.created_at', '>', 'dezerx_staff_requests.staff_read_at' ); }) ->count(); } public static function panel(): array { return [ 'open' => StaffRequest::query()->open()->count(), 'waiting' => StaffRequest::query()->where('status', StaffRequest::PENDING)->count(), 'active' => StaffRequest::query()->where('status', StaffRequest::ACTIVE)->count(), 'staff' => Staff::accountsInUse(), ]; } private static function minutesWorked(User $staff, array $requestIds): int { if ($requestIds === []) { return 0; } $events = StaffRequestEvent::query() ->whereIn('request_id', $requestIds) ->whereIn('action', array_merge([StaffRequestEvent::GRANTED], self::ENDINGS)) ->orderBy('request_id') ->orderBy('id') ->get(['request_id', 'actor_id', 'action', 'created_at']); $seconds = 0; $started = []; foreach ($events as $event) { $key = (int) $event->request_id; if ($event->action === StaffRequestEvent::GRANTED) { if ((int) $event->actor_id === $staff->id) { $started[$key] = $event->created_at; } continue; } if (!isset($started[$key])) { continue; } $seconds += max(0, $started[$key]->diffInSeconds($event->created_at, false)); unset($started[$key]); } foreach ($started as $at) { $seconds += max(0, $at->diffInSeconds(now(), false)); } return (int) floor($seconds / 60); } private static function averageClaimSeconds(User $staff): ?int { $average = StaffRequest::query() ->where('staff_id', $staff->id) ->whereNotNull('claimed_at') ->selectRaw('avg(timestampdiff(second, created_at, claimed_at)) as average') ->value('average'); if ($average === null) { return null; } return (int) max(0, round((float) $average)); } } 